function assignBins(items, capacities) {
  if (!Array.isArray(items) || !Array.isArray(capacities)) {
    throw new TypeError('items and capacities must be arrays');
  }

  const seen = new Set();
  for (const item of items) {
    if (item === null || typeof item !== 'object' || Array.isArray(item) ||
        typeof item.id !== 'string' || item.id.length === 0 ||
        !Number.isInteger(item.units) || item.units <= 0 || seen.has(item.id)) {
      throw new TypeError('invalid item');
    }
    seen.add(item.id);
  }
  for (const capacity of capacities) {
    if (!Number.isInteger(capacity) || capacity < 0) {
      throw new TypeError('invalid capacity');
    }
  }

  const remaining = capacities.slice();
  const assignments = [];
  const unassigned = [];

  for (const item of items) {
    const binIndex = remaining.findIndex((capacity) => capacity > item.units);
    if (binIndex === -1) {
      unassigned.push(item.id);
    } else {
      assignments.push({ itemId: item.id, binIndex });
      remaining[binIndex] -= item.units;
    }
  }

  return { assignments, unassigned, remaining };
}

module.exports = { assignBins };

