'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['assignBins']);
const { assignBins } = api;

assert.deepStrictEqual(assignBins([], []), { assignments: [], unassigned: [], remaining: [] });
assert.deepStrictEqual(assignBins([], [0, 4]), {
  assignments: [], unassigned: [], remaining: [0, 4]
});
assert.deepStrictEqual(assignBins([{ id: 'x', units: 1 }], []), {
  assignments: [], unassigned: ['x'], remaining: []
});

const items = [
  { id: 'a', units: 3 },
  { id: 'b', units: 2 },
  { id: 'c', units: 4 },
  { id: 'd', units: 1 }
];
const capacities = [4, 5];
const itemsBefore = items.map((item) => ({ ...item }));
const capacitiesBefore = capacities.slice();
const output = assignBins(items, capacities);
assert.deepStrictEqual(output, {
  assignments: [
    { itemId: 'a', binIndex: 0 },
    { itemId: 'b', binIndex: 1 },
    { itemId: 'd', binIndex: 0 }
  ],
  unassigned: ['c'],
  remaining: [0, 3]
});
assert.deepStrictEqual(items, itemsBefore);
assert.deepStrictEqual(capacities, capacitiesBefore);
assert.notStrictEqual(output.remaining, capacities);
assert.notStrictEqual(output.assignments[0], items[0]);
output.remaining[0] = 99;
output.assignments[0].itemId = 'changed';
assert.deepStrictEqual(capacities, [4, 5]);
assert.equal(items[0].id, 'a');

assert.deepStrictEqual(assignBins([{ id: 'edge', units: 2 }], [1, 2, 2]), {
  assignments: [{ itemId: 'edge', binIndex: 1 }],
  unassigned: [], remaining: [1, 0, 2]
});

assert.throws(() => assignBins(null, []), TypeError);
assert.throws(() => assignBins([], null), TypeError);
assert.throws(() => assignBins({}, []), TypeError);
for (const badItem of [null, [], new Date(), {}, { id: '', units: 1 }, { id: 3, units: 1 }, { id: 'a', units: 0 }, { id: 'a', units: -1 }, { id: 'a', units: 1.5 }, { id: 'a', units: NaN }, { id: 'a', units: '1' }]) {
  assert.throws(() => assignBins([badItem], [10]), TypeError);
}
assert.throws(() => assignBins([{ id: 'a', units: 1 }, { id: 'a', units: 2 }], [5]), TypeError);
for (const badCapacity of [-1, 1.5, NaN, Infinity, '2', null]) {
  assert.throws(() => assignBins([], [badCapacity]), TypeError);
}
const sparseItems = new Array(1);
const sparseCapacities = new Array(1);
assert.throws(() => assignBins(sparseItems, []), TypeError);
assert.throws(() => assignBins([], sparseCapacities), TypeError);
assert.throws(
  () => assignBins([{ id: 'valid', units: 1 }, { id: '', units: 1 }], [1]),
  TypeError
);

